INSERT INTO player_duties VALUES(1,1,'2025-26',1,'GK','짧은 빌드업 개시(압박 아래에서도 풀백·CB 배급 — 고정 원칙), 박스 장악, 미드블록 뒤 페널티 폭 전체 커버. 스위핑은 상시가 아니라 상황부.','Measured (3 matches): centroid pinned to his own goal-line (x~10.1-10.5), laterally central (y~46-53); broad shallow coverage across the full box width; one match shows the furthest off-line range — sweeping only when the game demanded. High action volume (74+ in one match).','HIGH — deep base + full-width coverage + build-up involvement exactly match the brief; no evidence of over-aggressive sweeping that would break the mid-block.','gk_sweeper/Build-Up is right for the build-up brief; measured depth says the sweeping is situational, so Balanced focus is acceptable in match variants (used in the 로저스 CAM preset). [확정 2026-07-05: gk_ballplaying/Build-Up — 숙련도 타이브레이커. 골라인+빌드업 화해.]','appearances player_id=1 ranks 1-3 (measured); tactic_observations build_up','MEDIUM-HIGH — heatmaps HIGH (API-measured); note top-3 selection bias (best matches only).');
INSERT INTO player_duties VALUES(2,1,'2025-26',2,'RB','수비 우선 라이트백: 상대 윙어 봉쇄, 우측 터치라인 폭 유지, 좌 풀백과 한 명씩만 전진(기본 규칙), 지배 시 늦은 박스 진입.','Measured (3 matches): y~15-20 in every match — never drifts inside. Flank HEIGHT varies with the brief: one match defensive-leaning (def 38%/mid 42%), one balanced (def 29%/mid 41%), one camped high (mid 46%/att 32%).','HIGH — width discipline is absolute; height modulates per game plan exactly as the one-at-a-time rule predicts.','fb_fullback/Versatile (optimal) fits the height modulation; switch to Defend focus for containment briefs (e.g. vs Liverpool, 로저스 CAM preset).','appearances player_id=2 ranks 1-3 (measured); tactic_observations in_possession/modulation','MEDIUM-HIGH — heatmaps HIGH; top-3 bias noted.');
INSERT INTO player_duties VALUES(3,1,'2025-26',3,'RCB','우측 듀얼·공중볼 앵커, 전진한 캐시 배후 커버, 소유 시 볼 들고 우중앙 미드필드로 스텝업, 파포스트 세트피스 위협.','Measured (3 matches): def|right 35-50% core, mid|centre 20-34% step-ins (largest vs Forest, x-centroid 33.6 in the highest-line match), att-third spikes only on set pieces (header goal vs Bologna away).','HIGH — textbook match between brief and footprint; the step-out carries are measured, not just narrated.','cb_defender/Balanced confirmed — measured midfield step-ins argue for Balanced over a pure-stopper Defend focus. [EVENT-STATS 2026-07-02: pass 96% (squad-best) — BPD now three-axis; optimal upgraded to cb_bpd/Build-Up.]','appearances 72-74 (measured); tactic_observations defence','MEDIUM-HIGH — heatmaps HIGH; top-3 bias noted.');
INSERT INTO player_duties VALUES(4,1,'2025-26',4,'LCB','좌측 볼 플레잉 CB: 캐리·패스로 좌 하프스페이스 전진, 디뉴/마첸과 인버티드 좌측 공격에 공급, 상대를 눌러둘 때 미드필드 진입. 세트피스 박스 진입.','Measured (3 matches): y~67-71 left-centre constant. Depth scales with control: deep vs Bologna (70% own third), stepping into the middle third vs Fulham (54% mid) and Forest (x up to 97 — header + penalty won). Attacking-third volume near zero in open play.','HIGH — progression happens by stepping UP the left-centre channel, exactly the BPD brief; never wanders off the left channel.','cb_bpd/Build-Up confirmed unambiguously.','appearances player_id=4 ranks 1-3 (measured); tactic_observations build_up','MEDIUM-HIGH — heatmaps HIGH; top-3 bias noted.');
INSERT INTO player_duties VALUES(5,1,'2025-26',5,'LB','공수 겸장 레프트백: 인버티드 공격을 위한 좌측 터치라인 폭 유지(로저스 컷인·디뉴 폭), 캐시와 반대로 한 명씩 전진, 크로스·컷백 배달. 수비 복귀와 공격 산출의 균형.','Measured (3 matches): y~82-84 touchline-hugging in all three; average height climbs 45→51→53 with attacking-third share 21%→35%→41% depending on the brief; 52-86 touches, big two-way volume. REINFORCED 2026-07-02 (5 grids incl. Crystal Palace A 7.7, Spurs A 6.9): height is venue-STABLE — mean advancement home ~49.6 vs away ~47.9 (tool y). His attacking-third volume persists away from home.','HIGH — constant width, modulated height; the cutback assist vs Liverpool (Rogers goal) is the duty executed at its peak.','fb_fullback/Versatile (optimal) for balance; measured movement actually fits fb_att_wb/Support best (cosine 0.89, kind=role). KEY CONTRAST vs Maatsen: Digne delivers the same two-way profile home OR away — pick him when the game plan must survive venue/opposition swings.','appearances player_id=5 ranks 1-3 (measured); tactic_observations in_possession','MEDIUM-HIGH — heatmaps HIGH; top-3 bias noted.');
INSERT INTO player_duties VALUES(6,1,'2025-26',6,'LB','공격형 레프트백 변형(디뉴의 균형형과 대비): 높고 넓은 시작 위치, 좌 하프스페이스로 바이라인까지 침투, 인버티드 좌윙어와 오버로드. 좌측 수비 레인 전체는 여전히 책임.','Measured (3 matches): avg height 44-56/100 (well past a normal FB), y~81-83; end-to-end left channel coverage in every match — own box to opposition byline; goal vs Maccabi from a byline run; Brentford match: 115 heat points, 100 touches, 6 tackles. REINFORCED 2026-07-02 (5 grids incl. Newcastle A 7.1, Feyenoord A 7.0): height is venue-SWINGY — mean advancement home ~51.6 vs away ~43.6 (tool y), the largest home/away split measured in the squad. High-and-wide profile is real but mostly a HOME phenomenon; away he tucks deep.','HIGH — the most front-foot footprint of any defender measured, and the two-way volume shows the defensive lane isn''t abandoned.','fb_att_wb/Attack for home/dominance briefs stands. KEY CONTRAST vs Digne: away or vs strong wingers his measured profile collapses toward a plain deep LB — prefer Digne there, or set Maatsen to a Defend-focus variant.','appearances player_id=6 ranks 1-3 (measured); tactic_observations modulation axis 4','MEDIUM-HIGH — heatmaps HIGH; top-3 bias noted.');
INSERT INTO player_duties VALUES(7,1,'2025-26',12,'LDM','피벗 앵커: 백4 스크린, 중앙 우측에 위치(오나나/틸레만스가 좌측 레인), 통제된 순환, 전진하는 좌측 커버. 간헐적 전진 캐리.','Measured: 26-match average-position sweep gives mean y=42.6 (12 right / 12 centre / 2 left) — a right-of-centre/central pivot; settled firmly right from October through the 11-win streak until his January injury. Depth: avg x mostly 39-54 — a halfway-line controller in dominant games (top-3 heatmaps show 47-66% middle-third share), deeper in contested ones. DE-BIASED 2026-07-02: added Chelsea A (6.7) and Liverpool A 2-0 loss (6.3) grids — position-pure aggregate still sits around halfway (tool y≈45) and the closest role kernel is dm_dlp/Roaming (0.83) vs dm_holding/Ball-Winning (0.58). ALSO: his pivot SIDE switched mid-season — Aug-mid-Oct left-of-centre (y~55-65), from the Spurs away win (19 Oct) onward consistently right (y~30-44) through the 11-win streak.','HIGH on screening/circulation. The "deep sitting anchor" framing is now REJECTED with a de-biased sample: he is a right-of-centre deep-lying playmaker. Side-switch (left→right, mid-Oct) coincides with the streak-era pivot geometry.','RDM slot confirmed; role updated: dm_dlp profile (kind=role: dm_dlp/Roaming 0.83). optimal row keeps dm_holding/Ball-Winning as the prescriptive safe choice — revisit after in-game validation. [EVENT-STATS 2026-07-02: REVERSAL of the dlp lean — function is squad-best ball-winning (8.4 duels won, 3.0 interceptions/match) at high pass volume (56/match, 87%). He is a ball-winning DLP hybrid: movement=dlp, function=holding. optimal dm_holding/Ball-Winning stands ON FUNCTION grounds; A/B vs dm_dlp/Roaming in-game remains the tiebreaker.] [확정 2026-07-05: dm_holding/Ball-Winning — 숙련 동률 시 기능 축 우선. A/B 종결.]','appearances player_id=12 ranks 1-3 (measured); tactic_observations modulation','HIGH on side and depth — settled by 26-match avg-position sweep + away/loss grid samples (2026-07-02).');
INSERT INTO player_duties VALUES(8,1,'2025-26',16,'ST','원톱 3중 임무: ⑴ 와이드 딜리버리를 위한 중앙 박스 점유 ⑵ 내려와 연결— 컷인하는 로저스/맥긴에 레이오프 ⑶ 전환 배출구로 뒷공간 채널 런(10번 공간을 열기 위한 와이드 드리프트).','Measured (3 matches): all three briefs visible and cleanly separated by game type — Sunderland: near-pure central box occupation (2 headers from wide deliveries); Liverpool: central box + left-channel link play with Rogers; Man City (away, counter brief): deeper average, transition lanes halfway-to-box, central-right channel bursts.','HIGH — the footprint reshapes per game plan while the goal output stays constant (2 goals in each of the three matches); this is the system''s most brief-obedient attacker.','st_advanced/Versatile confirmed exactly — Versatile captures the box-occupier/link/channel-runner trinity better than Attack (pure poacher) would. [SHOTMAP 2026-07-02: 103 shots/38ev, 84% in-box, 24 six-yard, 19 headers, xG/shot 0.19 — pure box-occupier arrival profile; st_advanced/Versatile stands, st_poacher would also be defensible on arrivals.]','appearances player_id=16 ranks 1-3 (measured); tactic_observations in_possession','MEDIUM-HIGH — heatmaps HIGH; top-3 bias noted but the three matches happen to span three distinct game types (home rout, home clash, away counter), which mitigates it.');
INSERT INTO player_duties VALUES(9,1,'2025-26',13,'CAM','중앙 10번: 피벗과 공격 연결, 늦은 박스 진입, 미들서드 캐리. 비소유 시 왓킨스와 함께 압박(4-4-2 블록).','MOST-USED position: 21 starts, 1759 min, avg 7.10, best 8.5 (Leeds A) — his highest per-90 axis. Measured Liverpool 4-2 heatmap: roaming central creator, goal + assist.','HIGH — carries the largest minute load at the highest average output.','cam_playmaker/Roaming viable as a first-team alternative to Buendía at 10; keeps his LW slot open for Malen/Sancho rotations.','player_match_positions player_id=13; appearances Liverpool CAM (measured)','HIGH — full-season API position sweep.');
INSERT INTO player_duties VALUES(10,1,'2025-26',13,'LW','인버티드 좌측 포워드: 높은 좌측 유지, 오른발 컷인, 중거리 슛, 오버래핑 디뉴/마첸과 연계.','BEST-CEILING position: 13 starts, avg 6.91 but the two best games of his season (9.3 West Ham, 9.0 Sunderland H) and measured peaks (8.84/8.46 heatmaps) are all here. Boom-or-quiet profile: lower floor than CAM, higher ceiling.','HIGH in big games; average delivery is less consistent than at CAM.','w_insidefwd/Attack (current optimal) is correct for max ceiling; if consistency is preferred, play him CAM and field a natural LW.','player_match_positions player_id=13; appearances 8.84/8.46 LW heatmaps','HIGH — full-season API position sweep.');
INSERT INTO player_duties VALUES(11,1,'2025-26',13,'RM','우측 공격수(비상·로테이션): 우측 폭 유지, 좌측 채널로 컷인.','WEAKEST axis: 8 starts, avg 6.33 — worst of any (player,position) pair in the squad sample. Measured best-RM heatmap (Man United A, 7.3) shows him constantly abandoning the flank to find central touches; the inverted-winger weapon does not transfer to the right.','LOW — the numbers and the movement pattern both say this deployment wastes him.','Do NOT map Rogers right in any game preset; if the right needs cover, McGinn or Guessand over Rogers.','player_match_positions player_id=13; appearances match_id=45 (measured)','HIGH — full-season API position sweep.');
INSERT INTO player_duties VALUES(12,1,'2025-26',14,'LW/left-10','전진 좌중앙 크리에이터: 좌 하프스페이스와 중앙 사이 자유 이동, 키패스, 세트피스 킥. 4-4-2 블록에서 세컨드 스트라이커로 압박.','MOST-USED position: 21 starts, 1541 min, avg 6.90 — AND his ceiling: 9.4 (Forest SF), 8.5 (Bournemouth), 8.3 (EL final) all measured LEFT-of-centre (centroids y64-72). The media "right-drift No.10" framing is dead: only 2 right-side starts all season.','HIGH in knockout/big matches; moderate consistency across the league season.','His optimal row is the No.10 (cam_playmaker/Roaming) — accurate IF the free role is understood as left-leaning; in a stricter setup use an AML/left-10 slot. Never map him right.','player_match_positions player_id=14; appearances 75-77 (measured)','HIGH — full-season API position sweep.');
INSERT INTO player_duties VALUES(13,1,'2025-26',14,'pivot-left','더 깊은 좌측 8번: 왕복 셔틀, 좌 하프스페이스 볼 순환, 늦은 박스 진입.','RELIABILITY position: 8 starts, avg 7.09 — his highest per-start average, above the advanced role. Measured (Newcastle A, 7.9, goal): def|left 31% + mid|left 22% genuine defensive work (4 tackles) plus a box arrival.','HIGH — quietly his most consistent deployment.','In-game: a CM/left-8 with Balanced or Build-Up focus is a legitimate second mapping for rotation-heavy setups; keeps his creativity while adding defensive presence.','player_match_positions player_id=14; appearances match_id=18 (measured)','HIGH — full-season API position sweep.');
INSERT INTO player_duties VALUES(14,1,'2025-26',10,'RM','미드필드 4의 우측: 블록에서 폭 유지, 소유 시 하프스페이스 런, 상대 LB 압박, 파포스트 도착.','MOST-USED position: 21 starts, 1672 min, avg 7.08, best 8.7 (Forest SF) + 8.6/8.5 — his ceiling games are all here. Measured heatmaps: right half-space and channel, edge-of-box arrivals (goals).','HIGH — the captain''s defining role in the streak side.','wm_widemid/Support (current optimal) confirmed for the foundation XI. [EVENT-STATS 2026-07-02: optimal upgraded to wm_insidefwd/Balanced (see player_role_map).] [SHOTMAP 2026-07-02: 0 headers, 1 six-yard in 46 shots, mean 17.1m, left-of-goal bias — edge-of-box inside-forward arrival, NOT a box striker; wm_insidefwd upgrade reinforced.]','player_match_positions player_id=10; appearances McGinn RM heatmaps','HIGH — full-season API position sweep.');
INSERT INTO player_duties VALUES(15,1,'2025-26',10,'pivot-right','더블 피벗 우측(딥 8번): 왕복 엔진, 압박 탈출 캐리, RB 지원, 늦은 도착.','BEST-AVERAGE position: 7 starts, avg 7.30 — higher than his RM average, concentrated in hostile away games. Measured (Feyenoord A, 7.9, goal): full-length two-way coverage (x3-99), mid|centre+mid|right core with real recovery work.','HIGH — trades width for control and his ratings rise.','Legit second mapping: CM-right/dm-adjacent role with Balanced focus for away/守-variant presets instead of a natural DM.','player_match_positions player_id=10; appearances match_id=3 (measured)','HIGH — full-season API position sweep.');
INSERT INTO player_duties VALUES(16,1,'2025-26',10,'CAM','중앙 10번(로테이션): 라인 사이 연결자, 세컨드 스트라이커 압박.','4 starts, avg 6.90. Measured (West Ham H, 7.8, goal): dead-central connector (mid|centre 35%), compact x29-87 — functional but his press/box-crash value is better spent wide-right or deep-right.','MEDIUM — serviceable, not additive.','Do not prefer; use only when both Buendía and Rogers are unavailable.','player_match_positions player_id=10; appearances match_id=22 (measured)','HIGH — full-season API position sweep.');
INSERT INTO player_duties VALUES(17,1,'2025-26',9,'pivot-left','피벗 좌측 딥라잉 플레이메이커: 딥에서 템포 지휘, 전진 패스, 늦은 박스 진입(EL 결승 득점).','MOST-USED and BEST position: 11 starts avg 7.32 (+10 centre starts avg 7.24 — same role straddling the lane boundary; combined 21 starts ~7.28), best 8.4 (EL final, goal). Measured heatmaps: deeper distributor left-of-centre.','HIGH — the streak side''s tempo source when Kamara was injured; season-best games came here.','dm_dlp/Build-Up (current bench mapping) confirmed — and he is the first-choice LDM partner for Kamara(RDM) in the corrected pivot geometry. [EVENT-STATS 2026-07-02: metronome verified on function — 87% pass, xA 0.30 (squad-best), xG 0.12: creator-from-deep, dm_dlp/Build-Up three-axis confirmed.] [SHOTMAP 2026-07-02: 5 headers + 4 six-yard among 30 shots — measured LATE box arrivals on top of the metronome game; supports Build-Up focus with late-arrival upside.]','player_match_positions player_id=9; appearances Tielemans deep heatmaps','HIGH — full-season API position sweep.');
INSERT INTO player_duties VALUES(18,1,'2025-26',9,'CAM','자유 10번(좌편향): 박스 크리에이터가 아니라 라인 사이를 깊게 연결하는 메트로놈.','7 starts, avg 7.24, best 8.4. Measured (Forest H, 7.9, assist): 123 touches in 90 min — nearly double a normal 10''s volume; left-leaning full-pitch distribution.','HIGH as a control-10; does not provide a classic creator''s box presence.','Viable control-variant 10 (cam_playmaker/Build-Up-ish) for matches where Villa expect to dominate possession; pivot remains his prime slot.','player_match_positions player_id=9; appearances match_id=41 (measured)','HIGH — full-season API position sweep.');
INSERT INTO player_duties VALUES(19,1,'2025-26',8,'pivot (all lanes)','더블 피벗의 박스투박스 쪽: 스크린·듀얼·박스 쇄도(헤더 득점). 파트너가 안 쓰는 레인을 가져간다.','SIDE-AGNOSTIC: 15 centre starts (avg 7.21, best 8.1), 8 right (7.04), 6 left (7.05) — near-identical output on all three lanes; left of Kamara in the streak, right of Tielemans after. Measured heatmaps on centre (Man City 8.1), left (Bournemouth 8.2) and right (Newcastle A 7.3) all show the same mid-block screening + box-surge pattern.','HIGH — the pivot''s universal adapter; his rating is partner-independent.','dm_boxcrasher/Balanced confirmed; slot him LDM or RDM freely per partner — corrected optimal XI has him LDM next to Kamara(RDM). [EVENT-STATS 2026-07-02: TENSION — best-game function reads box-crasher (6.6 duels, 2.3 aerials, lowest pivot pass volume 37/match), but this sample shares the dom-bias that season movement analysis corrected (optimal now dm_dlp/Roaming, season depth ~44). Resolution deferred to in-game A/B: dm_dlp/Roaming vs dm_boxcrasher/Balanced.] [SHOTMAP 2026-07-02: 35% of shots are headers — his box presence is largely set-piece aerial arrival; the boxcrash element is phase-specific, compatible with dm_dlp open-play movement.] [확정 2026-07-05: dm_holding/Roaming — 숙련도 타이브레이커(유일 숙련 DM). A/B 종결.]','player_match_positions player_id=8; appearances Onana heatmaps x4 (measured)','HIGH — full-season API position sweep.');
INSERT INTO player_duties VALUES(20,1,'2026-27',55,'LDM','영상·스카우트 분석 종합(가설): 캐리로 전진하는 B2B — 드리블 돌파보다 운반, 박스 침투 시 공중볼 위협, 중거리 슈팅, 롱스로 보유','클럽 실측: 딥 좌측 기본(좌2컬럼 50.4%), 태클 1.52·탈취 4.69/90 — 수비 기여 실재. 전진 배치는 대표팀에서만(전방 64.8%)','부분 일치 — 캐리 전진(온더볼)은 그리드 밖이라 미검증, 위치 주장은 실측이 정정','dm_dlp/Roaming 지지(캐리 전진형 딥롤). PlayStyles 확인 필요: 파워샷·긴스로인 보유 시 게임 재현 가산','obs#142 참조 (TFA·TransferFlow·X 스카우트)','서사+실측 교차검증 — 온더볼 주장만 가설 잔존');
INSERT INTO player_duties VALUES(21,1,'2026-27',58,'LM','영상 종합(가설): 컷인 후 파포스트 감아차기, 1v1 돌파·볼캐리, 카운터 위협','실측: 좌 편향(좌측 38경기), winger 커널 .771','정합 — 컷인형 윙어','wm_winger/Attack 유지. PlayStyles 확인: 트릭스터·퀵스텝 보유(수집됨)','obs#143','서사+실측 정합');
INSERT INTO player_duties VALUES(22,1,'2026-27',56,'LDM','영상 종합(가설): 볼위닝 destroyer + 박스 침투("6과 절반"), 프레스 저항 캐리, 약점 창의성','실측: 듀얼·태클 상위, dm_dlp/Roaming .763(위치 기준)','⭐ 긴장 — 위치는 dlp, 기능은 볼위너','dm_holding/Ball-Winning Δ 산출 후 처방 재검토(다음 세션)','obs#143','가설 — 커널 대조 대기');
INSERT INTO player_duties VALUES(23,1,'2026-27',57,'RCB','영상 종합(가설): 공중 지배(191cm)·후방 빌드업 개시·세트피스 골위협, CB/DM 겸업 가능','실측: cb_bpd/Aggressive .883 (29경기)','강정합','cb_bpd/Aggressive 유지. DM 겸업은 실측 표본 생기면 검증','obs#143','서사+실측 정합');
